32: export function AgentStreamProvider({
33:   children,
34:   seed = 0x5eed1e,
35:   tickMs = 1800,
36:   autoStart = true,
37:   engine: injectedEngine,
38: }: AgentStreamProviderProps) {
39:   const engineRef = useRef<MarketEngine | null>(injectedEngine ?? null);
40:   if (!engineRef.current) {
41:     engineRef.current = createMarketEngine({ seed, tickMs });
42:   }
43:   const engine = engineRef.current;
44:   const [snapshot, setSnapshot] = useState<DashboardSnapshot>(() => engine.latest);
45:   const [paused, setPaused] = useState(!autoStart);
46: 
47:   const advance = useCallback(
48:     (count = 1) => {
49:       let next = engine.latest;
50:       const steps = Math.max(1, Math.floor(count));
51:       for (let i = 0; i < steps; i += 1) next = engine.tick();
52:       setSnapshot(next);
53:     },
54:     [engine],
55:   );
