58:     if (paused) return;
59:     const handle = window.setInterval(() => {
60:       setSnapshot(engine.tick());
61:     }, tickMs);
62:     return () => window.clearInterval(handle);
63:   }, [engine, paused, tickMs]);
64: 
65:   const togglePause = useCallback(() => {
66:     setPaused((value) => !value);
67:   }, []);
